BEGIN;
CREATE TABLE app.supplier_fact_proposal(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,document_id uuid NOT NULL,document_version_id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),parser_version text NOT NULL,source_hash char(64) NOT NULL,document_type varchar(20) NOT NULL CHECK(document_type IN('invoice','credit')),quantity_decimal numeric(20,6),unit_price_pence bigint CHECK(unit_price_pence BETWEEN 0 AND 1000000000000),net_pence bigint CHECK(net_pence BETWEEN 0 AND 1000000000000),source_page integer NOT NULL CHECK(source_page>0),span_start integer NOT NULL CHECK(span_start>=0),span_end integer NOT NULL CHECK(span_end>=span_start),source_region text NOT NULL,issues jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,document_id,revision),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,document_id) REFERENCES app.supplier_document(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,document_version_id) REFERENCES app.supplier_document_version(tenant_id,job_id,id));
CREATE TABLE app.supplier_fact_revision(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,document_id uuid NOT NULL,proposal_id uuid NOT NULL,command_id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),actor_ref text NOT NULL,document_type varchar(20) NOT NULL CHECK(document_type IN('invoice','credit')),quantity_decimal numeric(20,6) NOT NULL CHECK(quantity_decimal>=0),unit_price_pence bigint NOT NULL CHECK(unit_price_pence BETWEEN 0 AND 1000000000000),net_pence bigint NOT NULL CHECK(net_pence BETWEEN 0 AND 1000000000000),origin varchar(30) NOT NULL CHECK(origin IN('source','entered_by_you')),disposition varchar(30),payload_hash char(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,command_id),UNIQUE(tenant_id,document_id,revision),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,document_id) REFERENCES app.supplier_document(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,proposal_id) REFERENCES app.supplier_fact_proposal(tenant_id,job_id,id),CHECK((document_type='invoice' AND net_pence>=0) OR (document_type='credit' AND net_pence>=0)));
DO $$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['supplier_fact_proposal','supplier_fact_revision'] LOOP EXECUTE format('ALTER TABLE app.%I OWNER TO jobguard_migration',n);EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE app.%I FORCE ROW LEVEL SECURITY',n);EXECUTE format('CREATE POLICY tenant_isolation ON app.%I FOR ALL TO jobguard_runtime,jobguard_migration USING(tenant_id=current_setting(''app.tenant_id'')::uuid) WITH CHECK(tenant_id=current_setting(''app.tenant_id'')::uuid)',n);EXECUTE format('GRANT SELECT,INSERT ON app.%I TO jobguard_runtime',n);EXECUTE format('REVOKE UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON app.%I FROM jobguard_runtime',n);END LOOP;END$$;
GRANT SELECT,INSERT ON app.supplier_fact_proposal,app.supplier_fact_revision TO jobguard_runtime;
REVOKE UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON app.supplier_fact_proposal,app.supplier_fact_revision FROM jobguard_runtime;
COMMIT;
